        var ctx = null;
        try { ctx = $.GetContextPanel ? $.GetContextPanel() : null; } catch (e0) { ctx = null; }
        if (IsPanelValid(ctx) && scanRoots.indexOf(ctx) === -1) scanRoots.push(ctx);
