        if (opened || IsHudClassActive(root, "gShopOpen")) {
            EnsureShopFavoritesNavActive(root, now, "buildCategoryPayloadFavoritesActionNextMs", BUILD_CATEGORY_PAYLOAD_UI_ACTION_COOLDOWN_MS);
        }
        return opened;
