        BuildSaveDebugLogThrottled(
            "write_entry_present|" + (entry ? "1" : "0"),
            "write attempt entryPresent=" + (entry ? "1" : "0") + " payloadLen=" + payloadText.length + " " + BuildSaveDebugSnapshot(root),
            nowMs
        );
